    "timer.soundsMade": { en: "These are generated by the app itself — no files, and they work offline.", ar: "هاي الأصوات التطبيق بولّدها بنفسه — بدون ملفات، وبتشتغل بدون إنترنت.", es: "La app genera estos sonidos ella misma: sin archivos y funcionan sin conexión.", fr: "Ces sons sont générés par l'application elle-même : aucun fichier, et ils fonctionnent hors ligne.", de: "Diese Töne erzeugt die App selbst — keine Dateien, und sie funktionieren offline.", ja: "これらの音はアプリ自身が生成します。ファイルは不要で、オフラインでも鳴ります。", zh: "这些声音由应用自己生成——无需文件，离线也能用。" },
    "timer.autoLogged": { en: "Countdown finished — {amount} {unit} logged", ar: "خلص العدّ التنازلي — انتسجّل {amount} {unit}", es: "Cuenta atrás terminada: {amount} {unit} registrados", fr: "Minuteur terminé — {amount} {unit} enregistrés", de: "Countdown beendet — {amount} {unit} erfasst", ja: "カウントダウン終了 — {amount} {unit} を記録", zh: "倒计时结束——已记录 {amount} {unit}" },
