    "timer.pickHint": { en: "Press one to hear it — it keeps playing until you press it again.", ar: "اضغط على أي واحد لتسمعه — بضل شغّال لحد ما تضغطه مرة ثانية.", es: "Pulsa uno para escucharlo: sigue sonando hasta que lo vuelvas a pulsar.", fr: "Appuyez pour l'écouter — il continue jusqu'à ce que vous appuyiez à nouveau.", de: "Antippen zum Anhören — er läuft weiter, bis du ihn erneut antippst.", ja: "押すと鳴ります。もう一度押すまで鳴り続けます。", zh: "点一下试听——再点一下才会停。" },
    "timer.soundsFiles": { en: "Downloaded once the first time you pick one, then kept for offline use.", ar: "بينزل أول مرة تختاره بس، وبعدها محفوظ ويشتغل بدون إنترنت.", es: "Se descarga la primera vez que eliges uno y luego queda guardado para usarlo sin conexión.", fr: "Téléchargé la première fois que vous en choisissez un, puis conservé pour un usage hors ligne.", de: "Wird beim ersten Auswählen einmal geladen und dann für die Offline-Nutzung behalten.", ja: "初めて選んだときに一度だけダウンロードし、その後はオフラインでも使えます。", zh: "第一次选择时下载一次，之后保存下来可离线使用。" },
